def resolve_roles(root=ROOT,people=None,chapters=None):
 root=Path(root);people=people if people is not None else{p['id']:p for p in json.loads((root/'registry/persons.json').read_bytes())['persons']};chapters=chapters or{};roles={}
 for role,seeds in SEEDS.items():
  endpoints=[]
  for s in seeds:
   ch=chapters.get(s['path'])
   if ch is None:ch=json.loads((root/s['path']).read_bytes())
   assert {k:ch[k]for k in s['dimensions']}==s['dimensions']
   p,=[p for p in ch['paragraphs']if p['id']==s['paragraph_id']];assert hashlib.sha256(p['text'].encode()).hexdigest()==s['paragraph_sha256']
   m,=[m for m in p['mentions']if m['id']==s['marker']['id']];assert {k:m[k]for k in s['marker']}==s['marker']and m['kind']=='person';assert p['text'][m['start']:m['end']]==m['surface']
   pid=m['person_id'];assert pid in people;actor=people[pid];assert[e for e in actor['evidence']if e.get('mention_id')==m['id']]==[s['reverse']];assert sum(a['surface']==m['surface']and m['id']in a['mention_ids']for a in actor['aliases'])==1;endpoints.append(pid)
  assert len(set(endpoints))==1;roles[role]=endpoints[0]
 assert len(set(roles.values()))==len(roles);return roles
